using System;
using System.IO;
using System.Collections.Generic;

class Program
{
    static void Main(string[] args)
    {
        string root = args.Length > 0 ? args[0] : ".";
        const long limit = 100L * 1024 * 1024; // 100 MB

        List<FileInfo> largeFiles = new List<FileInfo>();

        try
        {
            // Walk the directory tree manually to handle access exceptions per folder
            void EnumerateDirectory(string currentDir)
            {
                try
                {
                    foreach (string entry in Directory.GetFileSystemEntries(currentDir))
                    {
                        if (File.Exists(entry))
                        {
                            FileInfo fi = new FileInfo(entry);
                            if (fi.Length > limit)
                            {
                                largeFiles.Add(fi);
                            }
                        }
                        else if (Directory.Exists(entry))
                        {
                            EnumerateDirectory(entry);
                        }
                    }
                }
                catch (UnauthorizedAccessException)
                {
                    // Skip directories we don't have permission to read
                }
                catch (Exception ex)
                {
                    // Catch other potential IO exceptions during traversal
                    Console.WriteLine("Error accessing directory " + currentDir + ": " + ex.Message);
                }
            }

            EnumerateDirectory(root);

            // Sort files by size descending
            largeFiles.Sort((a, b) => b.Length.CompareTo(a.Length));

            foreach (FileInfo fi in largeFiles)
            {
                double sizeMB = fi.Length / 1048576.0;
                Console.WriteLine("{0,10:N1} MB  {1}", sizeMB, fi.FullName);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred during file traversal: " + ex.Message);
        }
    }
}
