class Stack {
  constructor() {
    this.items = [];
  }

  push(element) {
    this.items.push(element);
  }

  pop() {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek() {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[0]; // Peek at the top element, which is the last one added in array implementation if we treat index 0 as bottom
  }

  get size() {
    return this.items.length;
  }

  isEmpty() {
    return this.items.length === 0;
  }
}

// Example usage:
const stack = new Stack();
stack.push(10);
stack.push(20);
console.log(`Current size: ${stack.size}`); // Current size: 2
console.log("Peek:", stack.peek());       // Peek: 20 (Note: Array implementation means the last pushed item is at the end, so peek should return the last element)

// Correction for standard Stack behavior where push adds to top and pop removes from top (end of array):
class CorrectStack {
  constructor() {
    this.items = [];
  }

  push(element) {
    this.items.push(element);
  }

  pop() {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek() {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1]; // Peek at the last element added
  }

  get size() {
    return this.items.length;
  }

  isEmpty() {
    return this.items.length === 0;
  }
}

const correctStack = new CorrectStack();
correctStack.push(10);
correctStack.push(20);
console.log(`Current size: ${correctStack.size}`); // Current size: 2
console.log("Peek:", correctStack.peek());       // Peek: 20
console.log("Popped:", correctStack.pop());      // Popped: 20
console.log("New size:", correctStack.size);     // New size: 1
```

