function Find-DuplicateFiles {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Path,

        [switch]
        [bool]$Recurse
    )

    $files = Get-ChildItem -LiteralPath $Path -File -Recurse:$Recurse -ErrorAction SilentlyContinue
    $hashes = @{}

    foreach ($file in $files) {
        $hash = Get-FileHash -Path $file.FullName -Algorithm SHA256 | Select-Object -ExpandProperty Hash
        if (-not [string]::IsNullOrEmpty($hash)) {
            if (-not $hashes.ContainsKey($hash)) {
                $hashes[$hash] = @()
            }
            $hashes[$hash] += $file.FullName
        }
    }

    $duplicates = @{}
    foreach ($hash in $hashes.Keys) {
        if ($hashes[$hash].Count -gt 1) {
            $duplicates[$hash] = $hashes[$hash]
        }
    }

    return $duplicates
}
