using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace WordCounter
{
    internal class Program
    {
        static void Main(string[] args)
        {
            if (args.Length == 0)
            {
                Console.WriteLine("Please provide a file path as an argument.");
                return;
            }

            string filePath = args[0];

            if (!File.Exists(filePath))
            {
                Console.WriteLine($"Error: File not found at {filePath}");
                return;
            }

            try
            {
                // Read all lines and process them
                var lines = File.ReadAllLines(filePath);
                var wordCounts = new Dictionary<string, int>();

                foreach (string line in lines)
                {
                    // Simple tokenization: split by non-alphanumeric characters and convert to lower case
                    var words = line.Split(new char[] { ' ', '.', ',', '!', '?', ';', '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries);

                    foreach (string word in words)
                    {
                        if (!string.IsNullOrWhiteSpace(word))
                        {
                            string cleanWord = word.ToLower();
                            if (wordCounts.ContainsKey(cleanWord))
                                wordCounts[cleanWord]++;
                            else
                                wordCounts[cleanWord] = 1;
                        }
                    }
                }

                // Get the 10 most frequent words
                var topWords = wordCounts.OrderByDescending(kvp => kvp.Value)
                                         .Take(10);

                Console.WriteLine("Top 10 Most Frequent Words:");
                foreach (var item in topWords)
                {
                    Console.WriteLine($"{item.Key}: {item.Value}");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }
    }
}
