public class Program
{
    public static async Task Main(string[] args)
    {
        if (args.Length != 2)
        {
            Console.WriteLine("Usage: ConsoleApp <file1_path> <file2_path>");
            return;
        }

        string path1 = args[0];
        string path2 = args[1];

        try
        {
            Task<long> lengthTask1 = ReadFileLengthAsync(path1);
            Task<long> lengthTask2 = ReadFileLengthAsync(path2);

            long[] lengths = await Task.WhenAll(lengthTask1, lengthTask2);
            Console.WriteLine($"Combined length: {lengths[0] + lengths[1]} characters.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }

    private static async Task<long> ReadFileLengthAsync(string path)
    {
        if (!File.Exists(path))
        {
            throw new FileNotFoundException($"File not found at path: {path}");
        }
        // Since we only need the length, we can use FileInfo or stream it to count bytes/chars if needed, 
        // but for simplicity and adhering to async I/O pattern, we'll read all content asynchronously.
        string content = await File.ReadAllTextAsync(path);
        return content.Length;
    }
}
