public class ThreadSafeLruCache<TKey, TValue>
{
    private readonly int _capacity;
    private readonly LinkedList<TKey> _lruList = new LinkedList<TKey>();
    private readonly Dictionary<TKey, LinkedListNode<TKey>> _cacheMap = new Dictionary<TKey, LinkedListNode<TKey>>();
    private readonly Dictionary<TKey, TValue> _valueStore = new Dictionary<TKey, TValue>();
    private readonly object _lock = new object();

    public ThreadSafeLruCache(int capacity)
    {
        if (capacity <= 0) throw new ArgumentException("Capacity must be positive.");
        _capacity = capacity;
    }

    public bool Get(TKey key, out TValue value)
    {
        lock (_lock)
        {
            if (!_cacheMap.TryGetValue(key, out var node))
            {
                value = default;
                return false;
            }

            // Move accessed item to the front (most recently used)
            _lruList.Remove(node);
            _lruList.AddFirst(node);
            value = _valueStore[key];
            return true;
        }
    }

    public void Put(TKey key, TValue value)
    {
        lock (_lock)
        {
            if (_cacheMap.ContainsKey(key))
            {
                // Update existing item and move to front
                var node = _cacheMap[key];
                _valueStore[key] = value;
                _lruList.Remove(node);
                _lruList.AddFirst(node);
                return;
            }

            if (_cacheMap.Count >= _capacity)
            {
                // Evict the least recently used item (at the tail)
                var lruKey = _lruList.Last.Value;
                _lruList.RemoveLast();
                _cacheMap.Remove(lruKey);
                _valueStore.Remove(lruKey);
            }

            // Add new item to the front (most recently used)
            var newNode = _lruList.AddFirst(key);
            _cacheMap[key] = newNode;
            _valueStore[key] = value;
        }
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        var cache = new ThreadSafeLruCache<string, int>(3);

        cache.Put("A", 100);
        cache.Put("B", 200);
        cache.Put("C", 300);

        Console.WriteLine($"Get A: {GetCachedValue(cache, "A")}"); // Access A (MRU)
        cache.Put("D", 400); // Evicts B (LRU)

        Console.WriteLine($"Get B: {GetCachedValue(cache, "B")}"); // Should be null/default
        Console.WriteLine($"Get C: {GetCachedValue(cache, "C")}"); // Access C (MRU)
        Console.WriteLine($"Get A: {GetCachedValue(cache, "A")}"); // Access A (MRU)

        // Current order should be D, C, A (B evicted)
    }

    private static int? GetCachedValue(ThreadSafeLruCache<string, int> cache, string key)
    {
        if (cache.Get(key, out int value))
        {
            return value;
        }
        Console.WriteLine($"Key {key} not found.");
        return null;
    }
}
