using System;
using System.IO;
using System.Collections.Generic;

public class FileLister
{
    public static void Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: FileLister <folder_path>");
            return;
        }

        string startPath = args[0];
        if (!Directory.Exists(startPath))
        {
            Console.WriteLine($"Error: Directory not found at {startPath}");
            return;
        }

        List<FileInfo> allFiles = new List<FileInfo>();
        FindAllFilesRecursive(startPath, allFiles);

        // Sort files by size descending
        allFiles.Sort((a, b) => b.Length.CompareTo(a.Length));

        foreach (var file in allFiles)
        {
            if (file.Length > 100 * 1024 * 1024) // Check if size is greater than 100 MB
            {
                Console.WriteLine($"{file.FullName} ({file.Length / (1024.0 * 1024.0):F2} MB)");
            }
        }
    }

    private static void FindAllFilesRecursive(string directoryPath, List<FileInfo> fileList)
    {
        try
        {
            // Get all files in the current directory
            foreach (string filePath in Directory.GetFiles(directoryPath))
            {
                fileList.Add(new FileInfo(filePath));
            }

            // Get all subdirectories
            foreach (string subdirectoryPath in Directory.GetDirectories(directoryPath))
            {
                FindAllFilesRecursive(subdirectoryPath, fileList);
            }
        }
        catch (UnauthorizedAccessException)
        {
            // Ignore directories we don't have permission to access
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
