        // Simulate an operation that fails twice then succeeds
        int attempt = 0;
        if (attempt < 2)
        {
            throw new InvalidOperationException("Simulated failure.");
        }
        Console.WriteLine("Action succeeded.");
    }

    static void RetryAction(Action action, int maxRetries, int delayMs)
    {
        for (int i = 0; i < maxRetries; i++)
        {
            try
            {
                action();
                return; // Success, exit the method
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Attempt {i + 1} failed with exception type: {ex.GetType().Name}");
                if (i < maxRetries - 1)
                {
                    Thread.Sleep(delayMs); // Wait before next retry
                }
            }
        }
        Console.WriteLine("Action failed after maximum retries.");
    }

    static void Main(string[] args)
    {
        // Note: Since we cannot easily mock state in a simple static method without classes, 
        // the PerformAction above will always fail unless modified to track attempts externally.
        // For this example, we call it directly and rely on the loop structure.
        RetryAction(PerformAction, 3, 1000);
    }
}
