const fs = require('node:fs');

async function processId(id) {
  // Simulate asynchronous work
  await new Promise(resolve => setTimeout(resolve, Math.random() * 100));
  return `Processed ${id}`;
}

async function workerPool(ids, concurrency) {
  const results = [];
  const runningPromises = new Set();
  let index = 0;

  while (index < ids.length || runningPromises.size > 0) {
    if (runningPromises.size < concurrency && index < ids.length) {
      const currentId = ids[index];
      const promise = processId(currentId).then(result => {
        results.push(result);
        return result;
      });
      runningPromises.add(promise);

      // Remove the promise from the set when it settles
      promise.finally(() => runningPromises.delete(promise));
      index++;
    } else if (runningPromises.size > 0) {
      // Wait for at least one running promise to finish before checking again
      await Promise.race([...runningPromises]);
    }
  }
  return results;
}

const ids = Array.from({ length: 100 }, (_, i) => (i + 1).toString());
const concurrencyLimit = 4;

workerPool(ids, concurrencyLimit)
  .then(results => {
    console.log('All results:', results);
  })
  .catch(err => {
    console.error('An error occurred:', err);
  });
